changeSet.sql:
COMMENT ON TABLE TFPM_ADDR_ENRICH.IDEMPOTENCY_KEYS IS
    'Race-free deduplication. INSERT-first, catch ORA-00001 to detect duplicates.';
COMMENT ON COLUMN TFPM_ADDR_ENRICH.IDEMPOTENCY_KEYS.IDEM_KEY IS
    'SHA-256 hex of canonicalized raw address concatenated with source channel.';
COMMENT ON COLUMN TFPM_ADDR_ENRICH.IDEMPOTENCY_KEYS.RESULT_REF IS
    'FK to STRUCTURING_RESULTS.RESULT_ID. NULL means cascade in progress.';
